def transform(grid):
    g=[row[:] for row in grid]
    R,C=len(g),len(g[0]); centers=[]
    for r in range(1,R-1):
        for c in range(1,C-1):
            if all(grid[rr][cc]==2 for rr,cc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]):
                pass
            # diamond corners are diagonal? shapes have points top/bottom and left/right: test four corners at offsets
            if all(grid[rr][cc]==2 for rr,cc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]): centers.append((r,c))
    # identify center from diagonal 4-neighbor? diamond observed consists cardinal tips around empty center, yes
    for i,(r,c) in enumerate(centers):
        for rr,cc in centers[i+1:]:
            if r==rr:
                for x in range(min(c,cc)+2,max(c,cc)-1):
                    if g[r][x]==0:g[r][x]=1
            elif c==cc:
                for x in range(min(r,rr)+2,max(r,rr)-1):
                    if g[x][c]==0:g[x][c]=1
    return g
